CREATE OR REPLACE FUNCTION fn_concat(f_name character varying, l_name character varying) 
RETURNS character varying AS $$
BEGIN
    -- Check if both names are null
    IF f_name IS NULL AND l_name IS NULL THEN
        RETURN NULL;
    -- If only first name is null
    ELSIF f_name IS NULL AND l_name IS NOT NULL THEN
        RETURN l_name;
    -- If only last name is null
    ELSIF f_name IS NOT NULL AND l_name IS NULL THEN
        RETURN f_name;
    -- If both names are not null
    ELSE
        RETURN CONCAT(f_name, ' ', l_name);
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Example usage: Selecting all customer data along with the concatenated full name
SELECT c.customer_id, c.f_name, c.l_name, c.email, fn_concat(c.f_name, c.l_name) AS full_name
FROM cust c;

